--
-- Table structure for table `curriculum_feedback`
--

CREATE TABLE `curriculum_feedback` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `graduate_id` bigint(20) UNSIGNED NOT NULL,
  `question_id` bigint(20) UNSIGNED NOT NULL,
